import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { ApiService } from '../../core/services/api.service';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, RouterModule],
  template: `
    <div *ngIf="stats" class="fade-in">
      <h2 style="margin-bottom:1.5rem;">Dashboard</h2>
      <div class="grid grid-4" style="margin-bottom:2rem;">
        <div class="stat-card">
          <div class="stat-icon icon-primary"><span class="material-icons">place</span></div>
          <div class="stat-value">{{ stats.destinations }}</div>
          <div class="stat-label">Điểm đến</div>
        </div>
        <div class="stat-card">
          <div class="stat-icon icon-success"><span class="material-icons">tour</span></div>
          <div class="stat-value">{{ stats.tours }}</div>
          <div class="stat-label">Tours</div>
        </div>
        <div class="stat-card">
          <div class="stat-icon icon-warning"><span class="material-icons">article</span></div>
          <div class="stat-value">{{ stats.articles }}</div>
          <div class="stat-label">Bài viết</div>
        </div>
        <div class="stat-card">
          <div class="stat-icon icon-danger"><span class="material-icons">people</span></div>
          <div class="stat-value">{{ stats.users }}</div>
          <div class="stat-label">Người dùng</div>
        </div>
      </div>
      <div class="grid grid-3">
        <div class="stat-card"><div class="stat-icon icon-success"><span class="material-icons">star</span></div><div class="stat-value">{{ stats.reviews }}</div><div class="stat-label">Đánh giá</div></div>
        <div class="stat-card"><div class="stat-icon icon-warning"><span class="material-icons">pending</span></div><div class="stat-value">{{ stats.pendingInquiries }}</div><div class="stat-label">Yêu cầu chờ</div></div>
        <div class="stat-card"><div class="stat-icon icon-primary"><span class="material-icons">check_circle</span></div><div class="stat-value">{{ stats.activeUsers }}</div><div class="stat-label">User hoạt động</div></div>
      </div>

      <div class="grid grid-2" style="margin-top:2rem;">
        <div class="card">
          <div class="card-body">
            <h3>Yêu cầu gần đây</h3>
            <div *ngFor="let i of recentInquiries" class="mini-item">
              <div><strong>{{ i.name }}</strong> - {{ i.subject }}</div>
              <span class="badge" [class.badge-warning]="i.status==='pending'" [class.badge-success]="i.status==='replied'">{{ i.status }}</span>
            </div>
          </div>
        </div>
        <div class="card">
          <div class="card-body">
            <h3>Địa điểm xem nhiều nhất</h3>
            <div *ngFor="let d of topDestinations" class="mini-item">
              <div><strong>{{ d.name }}</strong></div>
              <span>{{ d.viewCount }} lượt xem</span>
            </div>
          </div>
        </div>
      </div>
    </div>
    <div class="loading-spinner" *ngIf="!stats"><div class="spinner"></div></div>
  `,
  styles: [`
    .mini-item { display: flex; justify-content: space-between; align-items: center; padding: 0.75rem 0; border-bottom: 1px solid #f1f5f9; font-size: 0.9375rem; &:last-child { border-bottom: none; } }
  `]
})
export class DashboardComponent implements OnInit {
  stats: any = null;
  recentInquiries: any[] = [];
  topDestinations: any[] = [];
  constructor(private api: ApiService) {}
  ngOnInit() {
    this.api.getDashboard().subscribe(data => {
      this.stats = data.stats;
      this.recentInquiries = data.recentInquiries;
      this.topDestinations = data.topDestinations;
    });
  }
}
